    },
    {
      "campo": "resolucao.passos[3].conta",
      "depois": "V2→V1: W < 0; ΔU = 0",
      "motivo": "Cabe na tela do celular sem quebrar."
    },
    {
      "campo": "resolucao.passos[4].conta",
      "depois": "I: V · II: F · III: F",
      "motivo": "Separadores mais legíveis."
    },
    {
      "campo": "resolucao.erradas.A",
      "depois": "Quem marcou A não viu que a I é verdadeira. Em BC: W = 0 e ΔU < 0, logo Q < 0. Em CA: ΔU = 0 e W < 0, logo Q = W < 0. Nos dois casos o gás libera calor.",
